// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAnnotations The comments on one target, or on a project
	// (GET /v1/annotations)
	ListAnnotations(ctx context.Context, request ListAnnotationsRequestObject) (ListAnnotationsResponseObject, error)
	// CreateAnnotation Comment on a clip, a render or a version of a timeline
	// (POST /v1/annotations)
	CreateAnnotation(ctx context.Context, request CreateAnnotationRequestObject) (CreateAnnotationResponseObject, error)
	// DeleteAnnotation Delete a comment
	// (DELETE /v1/annotations/{id})
	DeleteAnnotation(ctx context.Context, request DeleteAnnotationRequestObject) (DeleteAnnotationResponseObject, error)
	// UpdateAnnotation Edit, resolve or reopen a comment
	// (PATCH /v1/annotations/{id})
	UpdateAnnotation(ctx context.Context, request UpdateAnnotationRequestObject) (UpdateAnnotationResponseObject, error)
	// ListAssets List the workspace's assets, newest first
	// (GET /v1/assets)
	ListAssets(ctx context.Context, request ListAssetsRequestObject) (ListAssetsResponseObject, error)
	// CreateAsset Start an upload
	// (POST /v1/assets)
	CreateAsset(ctx context.Context, request CreateAssetRequestObject) (CreateAssetResponseObject, error)
	// DeleteAsset Delete an asset
	// (DELETE /v1/assets/{id})
	DeleteAsset(ctx context.Context, request DeleteAssetRequestObject) (DeleteAssetResponseObject, error)
	// GetAsset One asset
	// (GET /v1/assets/{id})
	GetAsset(ctx context.Context, request GetAssetRequestObject) (GetAssetResponseObject, error)
	// UpdateAsset Edit an asset's title
	// (PATCH /v1/assets/{id})
	UpdateAsset(ctx context.Context, request UpdateAssetRequestObject) (UpdateAssetResponseObject, error)
	// CompleteAssetUpload Finish an upload
	// (POST /v1/assets/{id}/complete)
	CompleteAssetUpload(ctx context.Context, request CompleteAssetUploadRequestObject) (CompleteAssetUploadResponseObject, error)
	// PresignAssetParts Presigned URLs for more parts
	// (POST /v1/assets/{id}/parts)
	PresignAssetParts(ctx context.Context, request PresignAssetPartsRequestObject) (PresignAssetPartsResponseObject, error)
	// GetAssetSpriteVtt The hover-scrub thumbnails track, with working URLs
	// (GET /v1/assets/{id}/sprite.vtt)
	GetAssetSpriteVtt(ctx context.Context, request GetAssetSpriteVttRequestObject) (GetAssetSpriteVttResponseObject, error)
	// GetAssetTranscript The words spoken in an asset, with timings and speech structure
	// (GET /v1/assets/{id}/transcript)
	GetAssetTranscript(ctx context.Context, request GetAssetTranscriptRequestObject) (GetAssetTranscriptResponseObject, error)
	// AbortAssetUpload Abort an upload
	// (DELETE /v1/assets/{id}/upload)
	AbortAssetUpload(ctx context.Context, request AbortAssetUploadRequestObject) (AbortAssetUploadResponseObject, error)
	// GetAssetUpload The state of an upload, to resume it
	// (GET /v1/assets/{id}/upload)
	GetAssetUpload(ctx context.Context, request GetAssetUploadRequestObject) (GetAssetUploadResponseObject, error)
	// GetLibrarySummary Counts of the workspace's library
	// (GET /v1/library/summary)
	GetLibrarySummary(ctx context.Context, request GetLibrarySummaryRequestObject) (GetLibrarySummaryResponseObject, error)
	// GetMe The signed-in user, the active workspace and its plan
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ListProjects List the workspace's projects, newest first
	// (GET /v1/projects)
	ListProjects(ctx context.Context, request ListProjectsRequestObject) (ListProjectsResponseObject, error)
	// CreateProject Start a project
	// (POST /v1/projects)
	CreateProject(ctx context.Context, request CreateProjectRequestObject) (CreateProjectResponseObject, error)
	// DeleteProject Delete a project
	// (DELETE /v1/projects/{id})
	DeleteProject(ctx context.Context, request DeleteProjectRequestObject) (DeleteProjectResponseObject, error)
	// GetProject One project, with its footage and current timeline version
	// (GET /v1/projects/{id})
	GetProject(ctx context.Context, request GetProjectRequestObject) (GetProjectResponseObject, error)
	// StartEdit Start an editor run on the project
	// (POST /v1/projects/{id}/edit)
	StartEdit(ctx context.Context, request StartEditRequestObject) (StartEditResponseObject, error)
	// ListRenders The renders of a project, newest first
	// (GET /v1/projects/{id}/renders)
	ListRenders(ctx context.Context, request ListRendersRequestObject) (ListRendersResponseObject, error)
	// CreateRender Render a version of the project's timeline
	// (POST /v1/projects/{id}/renders)
	CreateRender(ctx context.Context, request CreateRenderRequestObject) (CreateRenderResponseObject, error)
	// ListTimelineVersions The versions of a project's timeline, newest first
	// (GET /v1/projects/{id}/timelines)
	ListTimelineVersions(ctx context.Context, request ListTimelineVersionsRequestObject) (ListTimelineVersionsResponseObject, error)
	// ApplyTimelineOps Edit the timeline with ops (a manual tweak, or the editor agent's tool)
	// (POST /v1/projects/{id}/timelines)
	ApplyTimelineOps(ctx context.Context, request ApplyTimelineOpsRequestObject) (ApplyTimelineOpsResponseObject, error)
	// GetTimelineVersion One version of a project's timeline, with its spec and validation issues
	// (GET /v1/projects/{id}/timelines/{version})
	GetTimelineVersion(ctx context.Context, request GetTimelineVersionRequestObject) (GetTimelineVersionResponseObject, error)
	// GetRender One render, with its progress and, once ready, presigned URLs for its files
	// (GET /v1/renders/{id})
	GetRender(ctx context.Context, request GetRenderRequestObject) (GetRenderResponseObject, error)
	// GetRun A run, with its cost and a summary of its events
	// (GET /v1/runs/{id})
	GetRun(ctx context.Context, request GetRunRequestObject) (GetRunResponseObject, error)
	// GetRunArtifacts The artifacts of a run, with their full data
	// (GET /v1/runs/{id}/artifacts)
	GetRunArtifacts(ctx context.Context, request GetRunArtifactsRequestObject) (GetRunArtifactsResponseObject, error)
	// CancelRun Cancel a run
	// (POST /v1/runs/{id}/cancel)
	CancelRun(ctx context.Context, request CancelRunRequestObject) (CancelRunResponseObject, error)
	// ReplyToRun Answer a question of a run that waits for input
	// (POST /v1/runs/{id}/reply)
	ReplyToRun(ctx context.Context, request ReplyToRunRequestObject) (ReplyToRunResponseObject, error)
	// ResetStyle Forget the creator's style
	// (DELETE /v1/style)
	ResetStyle(ctx context.Context, request ResetStyleRequestObject) (ResetStyleResponseObject, error)
	// GetStyle The creator's style
	// (GET /v1/style)
	GetStyle(ctx context.Context, request GetStyleRequestObject) (GetStyleResponseObject, error)
	// UpdateStyle Set the creator's settings
	// (PUT /v1/style)
	UpdateStyle(ctx context.Context, request UpdateStyleRequestObject) (UpdateStyleResponseObject, error)
	// RemoveStyleReference Remove a reference video
	// (DELETE /v1/style/references/{id})
	RemoveStyleReference(ctx context.Context, request RemoveStyleReferenceRequestObject) (RemoveStyleReferenceResponseObject, error)
	// RelearnStyle Learn the style again from the reference videos
	// (POST /v1/style/relearn)
	RelearnStyle(ctx context.Context, request RelearnStyleRequestObject) (RelearnStyleResponseObject, error)
	// GetWorkspacePlan The plan of the active workspace and what it includes
	// (GET /v1/workspace/plan)
	GetWorkspacePlan(ctx context.Context, request GetWorkspacePlanRequestObject) (GetWorkspacePlanResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

